#include <fstream>
class MyFileStream {
public:
    std::ofstream ofs;
    // Move assignment operator
    MyFileStream& operator=(MyFileStream&& rhs) noexcept {
        if (this != &rhs) {
            ofs = std::move(rhs.ofs);
        }
        return *this;
    }
};
int main() {
    MyFileStream mfs1;
    MyFileStream mfs2;
    mfs2 = std::move(mfs1); // Move assignment from mfs1 to mfs2
    return 0;
}
